window.RESEARCH_STORY_V3 = {"version": 3, "title": "Version 3 · Three research directions from SharedVP", "subtitle": "Problem → existing work → gaps → focused first tests", "status": "Discussion version; no new ratings or established novelty claims", "designIntent": "One visual argument per slide; restrained monochrome framing, whitespace, readable figures. Preserve interactive charts and source drilldowns. Use source-year/venue labels when literature is shown. Detailed evidence and caveats live in speaker notes.", "sourceFiles": ["content/compiled-story-v2.json", "content/previous-work.json", "content/illumination-research-story.json", "content/agents-research-story.json", "content/robotics-research-story.json", "content/latest-direction-evaluation.json"], "slides": [{"id": "v3-opening", "chapter": "Shared virtual production", "kind": "v3-opening", "title": "Shared Workspaces for Virtual Production in Mixed Reality", "lead": "Our prototype reveals three limitations.", "speakerNotes": "Start from the submitted SharedVP work, not a new system claim. The existing workspace supports collaborative planning and static-shot exploration. Use exactly one source frame per category: lighting-onset-neutral shows a virtual performer within the physical room; actor-animation shows a selected animation pose; equipment-camera shows the camera twin without selection outlines. These are illustrative demo frames, not matched experimental comparisons. Current limitations are the user's account of their prototype: lighting/occlusion mismatches, selecting existing motion rather than generating directed behavior, and virtual-only equipment parameters. The exploratory study involved 12 participants in three teams and three static shots; it did not validate new relighting, generated character control or physical robotic execution. Updated representative images: the user-supplied on-set screenshot includes virtual performers/props and physical stage equipment; the second is the paired animation at 3:20; the third is the wide light/stand view at 3:06. Images retain original color and full framing. They illustrate the existing prototype, not a controlled illumination test, newly generated interaction or physical robot actuation.", "transition": "Each limitation becomes one research goal.", "paperIds": [], "panels": [{"title": "Lighting and occlusion", "topicId": "illumination", "image": "assets/demo/opening-mixed-production.png", "limit": "Real and virtual content do not share consistent lighting or occlusion."}, {"title": "Actor direction", "topicId": "agents", "image": "assets/demo/actor-interaction.jpg", "limit": "Place actors; select existing animation and poses."}, {"title": "Equipment twins", "topicId": "robotics", "image": "assets/demo/equipment-overview.jpg", "limit": "Parameter edits affect virtual equipment only."}]}, {"id": "v3-directions", "chapter": "Shared virtual production", "kind": "v3-directions", "title": "Three research directions", "lead": "Make the shared plan respond to creative decisions.", "speakerNotes": "These are candidate directions, not three simultaneous promises. Each stays anchored in the shared virtual-production setting and can have broader MR, animation or HRI value. Use the approved static illustrations, not GIFs. Lighting concerns appearance across physical and virtual subjects. Agents concern responsive and editable performance. XR robotics concerns understandable interaction with equipment that may execute physically.", "transition": "First: make light behave coherently across the mixed set.", "paperIds": [], "cards": [{"title": "Bidirectional illumination", "topicId": "illumination", "goal": "Make real and virtual subjects share light.", "image": "assets/directions/illumination-illustration-v4.png"}, {"title": "Directable virtual agents", "topicId": "agents", "goal": "Turn directing notes into editable performances.", "image": "assets/directions/agents-illustration-v4.png"}, {"title": "Human–robot interaction in XR", "topicId": "robotics", "goal": "Translate spatial intent into equipment action.", "image": "assets/directions/robotics-illustration-v4.png"}]}, {"id": "v3-light-goal", "chapter": "1 · Illumination", "kind": "v3-motivation", "title": "Bidirectional Illumination in Mixed Reality", "lead": "", "speakerNotes": "Production motivation: a filmmaker should place physical or virtual lights and anticipate their effects on both physical and virtual actors, props and surroundings. Include nearby point/spot sources and distant environment illumination, warm/cool color temperature, direct and indirect light, shadows and material response in the visual, not a dense list. Existing lighting estimation, differential rendering and relighting are achievements to acknowledge. The gap is not that bidirectional lighting never exists; it is the remaining consistency and update limitations for our dynamic, stereo, interactive production task. Video see-through changes captured appearance; it does not physically emit virtual photons into the room. Broader MR perception is secondary to this production goal. Overview refinement from the user: distinguish real-time global/environment estimation from accurate local real illumination at the virtual subject. Local approaches already exist (HandLight, LiMo); do not claim local estimation is absent. For the reverse direction, image/video relighting achievements do not establish a live, stereo-consistent XR pipeline. GenLit v2 Section10 reports a single point source, retained baked-in shadows and slow inference. LightLab reports model inference rather than full headset latency. DepthLab and HybRelighter are existing live baselines, not evidence that XR relighting is absent. HybRelighter explicitly targets dynamically updating scenes, so do not say every XR method is static or cannot handle dynamics. Instead compare preparation/geometry assumptions, actual moving-content demonstrations and stereo/end-to-end validation. Support across point, spot, area and environment lighting is uneven; specific support is examined in the following literature slides, not claimed universally missing. Distinguish captured-pixel relighting from physically illuminating real objects. Primary checks: https://arxiv.org/html/2412.11224v2#S10 and https://arxiv.org/html/2508.14930v1 .", "transition": "Use the next literature slides to examine these gaps by direction, technique, view and runtime evidence.", "paperIds": ["handlight", "limo", "genlit", "lightlab", "depthlab", "review-ref-85"], "topicId": "illumination", "bullets": ["Real-time environment lighting is established; reliable nearby-light estimation remains difficult.", "Image/video relighting is strong, often offline. Live XR still challenges shadowed detail, stereo consistency and changing scenes."], "goal": "Preview physical and virtual lights across the whole mixed set.", "image": "assets/directions/illumination-illustration-v4.png", "directionSummary": [{"label": "Real light → virtual content", "text": "Real-time environment lighting is established; reliable nearby-light estimation remains difficult."}, {"label": "Virtual light → real imagery", "text": "Image/video relighting is strong, often offline. Live XR still challenges shadowed detail, stereo consistency and changing scenes."}], "sharedGap": "Across both: support for different light types remains uneven."}, {"id": "v3-light-directions", "chapter": "1 · Illumination", "kind": "v3-direction-chart", "title": "Relighting research at a glance", "lead": "", "speakerNotes": "Count the reviewed corpus, not the entire research field. Use an explicit mutually exclusive primary-direction assignment for a pie; methods supporting both directions need their own slice rather than double counting. Surveys and unclassified papers stay visible as separate categories. Display exact n and category labels on or adjacent to slices. Clicking virtual-light-to-real opens the following linked drilldown. A small slice is a coverage observation, not proof of novelty. Recent papers receive emphasis; older foundations remain available. No precomputed counts are invented in this content file. Counting context belongs in presenter notes, not audience copy: this is the reviewed corpus rather than a field census. Each record has one primary role. The33 related records comprise16 supporting methods/resources,7 perception studies,5 physical-projection methods,4 mixed estimation/relighting records and1 unassessed record. Keep these distinct from the17 both-direction/composition records. Sector labels are embedded in the pie; source membership remains clickable. Charts count exclusive groups within the indicated reviewed branch. AR/MR output does not imply real-time or stereo validation; runtime remains a separate chart. Locality gives precedence to combined local/global, then local, spatially varying, global and unassessed. Clicking a segment updates the adjacent recent-paper panel, with the full category accessible through All sources.", "transition": "Now inspect virtual light on captured real scenes.", "paperIds": ["depthlab", "review-ref-85", "handlight", "limo", "delta"], "topicId": "illumination", "chart": {"id": "lighting-direction", "topicId": "illumination", "mode": "primary-direction", "field": "sourceGroup", "includeSurveys": true, "showUnknown": true, "countUnit": "unique paper", "denominator": "reviewed illumination corpus", "labels": "on-or-near-slice", "drilldownTarget": "v3-light-drilldown", "focus": "Virtual light → captured real scene"}}, {"id": "v3-light-drilldown", "chapter": "1 · Illumination", "kind": "v3-drilldown", "title": "Virtual light → real imagery", "lead": "", "speakerNotes": "The subset must be linked from the preceding direction chart, with its denominator displayed. Three coordinated distributions show output form (single image / video or live stream / stereo MR / unknown), technique (depth or geometry effect / explicit light transport / learned or generative relighting / mixed / unknown), and runtime evidence. Technique groups describe demonstrated mechanisms, not title keywords. Keep preparation/reconstruction cost distinct from lighting update and rendering cost: real-time rendering after offline reconstruction is not an end-to-end real-time system. Unknown timing is neither real-time nor offline. Distinguish measured stage time, demonstrated interactive updates, offline operation and missing evidence. Charts use existing reviewed classifications; do not silently infer unsupported labels. A click reveals the actual paper set with years/venues and evidence. Charts count exclusive groups within the indicated reviewed branch. AR/MR output does not imply real-time or stereo validation; runtime remains a separate chart. Locality gives precedence to combined local/global, then local, spatially varying, global and unassessed. Clicking a segment updates the adjacent recent-paper panel, with the full category accessible through All sources.", "transition": "Those results point to three production-specific questions.", "paperIds": ["depthlab", "review-ref-85", "review-ref-35", "delta", "lightlab", "genlit"], "topicId": "illumination", "chart": {"id": "captured-real-drilldown", "topicId": "illumination", "mode": "linked-distributions", "parentChartId": "lighting-direction", "subset": "virtual-light-to-captured-real", "dimensions": [{"id": "output", "label": "Image, video or stereo MR?"}, {"id": "technique", "label": "How is appearance changed?"}, {"id": "runtime", "label": "Which stage runs live?"}], "showUnknown": true, "includeSurveys": false, "countUnit": "unique paper per chart", "labels": "on-or-near-slice"}, "branchId": "virtual-to-captured", "branchLabel": "Virtual → real"}, {"id": "v3-light-both", "chapter": "1 · Illumination", "kind": "v3-drilldown", "title": "Both lighting directions", "lead": "", "speakerNotes": "The subset must be linked from the preceding direction chart, with its denominator displayed. Three coordinated distributions show output form (single image / video or live stream / stereo MR / unknown), technique (depth or geometry effect / explicit light transport / learned or generative relighting / mixed / unknown), and runtime evidence. Technique groups describe demonstrated mechanisms, not title keywords. Keep preparation/reconstruction cost distinct from lighting update and rendering cost: real-time rendering after offline reconstruction is not an end-to-end real-time system. Unknown timing is neither real-time nor offline. Distinguish measured stage time, demonstrated interactive updates, offline operation and missing evidence. Charts use existing reviewed classifications; do not silently infer unsupported labels. A click reveals the actual paper set with years/venues and evidence. Charts count exclusive groups within the indicated reviewed branch. AR/MR output does not imply real-time or stereo validation; runtime remains a separate chart. Locality gives precedence to combined local/global, then local, spatially varying, global and unassessed. Clicking a segment updates the adjacent recent-paper panel, with the full category accessible through All sources.", "transition": "Those results point to three production-specific questions.", "paperIds": ["depthlab", "review-ref-85", "review-ref-35", "delta", "lightlab", "genlit"], "topicId": "illumination", "chart": {"id": "captured-real-drilldown", "topicId": "illumination", "mode": "linked-distributions", "parentChartId": "lighting-direction", "subset": "virtual-light-to-captured-real", "dimensions": [{"id": "output", "label": "Image, video or stereo MR?"}, {"id": "technique", "label": "How is appearance changed?"}, {"id": "runtime", "label": "Which stage runs live?"}], "showUnknown": true, "includeSurveys": false, "countUnit": "unique paper per chart", "labels": "on-or-near-slice"}, "branchId": "both-directions", "branchLabel": "Both directions"}, {"id": "v3-light-subtopics", "chapter": "1 · Illumination", "kind": "v3-subtopics", "title": "Three illumination subtopics", "lead": "", "speakerNotes": "These summaries match the subsequent I1, I2 and I3 slides. I1: weak image evidence in dark regions, geometry artifacts and stereo/live performance motivate relighting and possible LDR-to-HDR preprocessing. I2: distinguish training coverage from independently controllable source types and shadow parameters; compare light-type controls with live XR constraints. I3: incident-light estimation and visibility of real occluders are separate requirements; HandLight and other probes are components rather than a complete shadow solution. Each is a candidate research direction, with source-specific limits and discriminating tests on the following slide.", "transition": "Begin with a virtual spotlight and a real prop.", "paperIds": ["depthlab", "review-ref-85", "genlit", "lightlab", "review-ref-65", "handlight", "limo", "review-ref-75"], "topicId": "illumination", "items": [{"title": "I1 · Virtual light on real video see-through imagery", "question": "Relight dark or shadowed real subjects, reduce geometry artifacts, and maintain responsive, stereo-consistent XR.", "paperIds": ["depthlab", "review-ref-85", "genlit", "lightlab"]}, {"title": "I2 · Light-type effects on shadows and illumination in XR", "question": "Control point, area, spot and environment lighting, including shadow softness and color temperature, in XR.", "paperIds": ["genlit", "lightlab", "review-ref-65", "handlight"]}, {"title": "I3 · Local real lighting and shadows on virtual content", "question": "Estimate nearby real lighting at virtual subjects and account for shadows cast onto them by real objects.", "paperIds": ["handlight", "limo", "review-ref-75", "review-ref-65"]}]}, {"id": "v3-light-i1", "chapter": "1 · Illumination", "kind": "v3-method-focus", "title": "I1 · Virtual light on real video see-through imagery", "lead": "", "speakerNotes": "Existing: DepthLab supplies a runnable depth-based baseline; HybRelighter filters geometry-based lighting and Reciprocal Shading explores transport. The remaining failure must be demonstrated relative to these baselines, not assumed from a literature label. Begin with a controlled rigid prop, one virtual spotlight and diffuse/rough materials; capture a matched physical-lamp reference with stable exposure and synchronized depth/pose. Compare mesh-only, filtered geometry and any correction at matched compute. Measure shadow boundary, material/color drift, flicker and end-to-end update delay. Dark regions have little recoverable signal; distinguish physically supported recovery from plausible synthesis. Synthetic OpenRooms or static Objects with Lighting data support ablations but do not substitute dynamic MR reference sequences. Updated focus: distinguish scarce sensor information in dark/underexposed areas from scarcity of training data. Brightening can amplify noise; inferred HDR radiance is not guaranteed recovery of hidden surface texture or reflectance. Liu et al., Single-Image HDR Reconstruction by Learning to Reverse the Camera Pipeline (CVPR 2020), explicitly addresses quantization/saturation and under-/overexposed regions; consider it a preprocessing baseline, not proven XR relighting. HybRelighter §§2.4,3.4,4 corrects low-quality mesh artifacts, demonstrates dynamic geometry and a handheld live pipeline, but cannot consistently distinguish existing shadows from reconstruction errors. GenLit §10 reports retained self-shadows and slow inference. Do not claim all image relighting is offline: evaluate live methods separately; fast monocular output does not by itself demonstrate binocular correspondence. Stereo error should compare reprojected corresponding surfaces while respecting view-dependent reflectance and disocclusion. Profile capture, geometry/preparation, relighting, stereo and display separately. Sources: https://arxiv.org/abs/2004.01179; https://arxiv.org/html/2508.14930v1 (§§2.4,3.4,4); https://arxiv.org/html/2412.11224v2 (§10).", "transition": "Which lighting errors actually matter for a shot?", "paperIds": ["depthlab", "review-ref-85", "genlit", "lightlab"], "topicId": "illumination", "question": "Can virtual lighting reveal shadowed detail while staying stable in live stereo XR?", "existing": "Depth and mesh methods enable live effects; diffusion models produce rich image-based relighting.", "gap": "Dark pixels contain weak detail; geometry creates artifacts. Fast single-view results do not establish stereo consistency.", "firstTest": "Test LDR→HDR preprocessing and geometry-guided relighting on a moving prop; measure detail, stereo error and end-to-end latency.", "image": "assets/papers/review-ref-85.jpg", "paperExamples": [{"id": "depthlab", "name": "DepthLab", "venue": "UIST", "contribution": "Depth-based live effects; scene depth quality limits alignment."}, {"id": "review-ref-85", "name": "HybRelighter", "venue": "arXiv preprint", "contribution": "Live mesh correction; shadows remain ambiguous with geometry errors."}, {"id": "genlit", "name": "GenLit", "venue": "SIGGRAPH Asia", "contribution": "Rich generated relighting; baked-in shadows and slow inference remain."}, {"id": "lightlab", "name": "LightLab", "venue": "SIGGRAPH", "contribution": "Color/intensity image edits; stereo XR is not established by single-image results."}], "resourceLinks": [{"label": "Candidate: Single-Image HDR Reconstruction · CVPR 2020", "url": "https://arxiv.org/abs/2004.01179"}], "gaps": ["Dark regions provide weak or missing surface detail.", "Mesh errors distort shading and shadow boundaries.", "Generative relighting can exceed the XR frame budget.", "Single-view quality does not establish stereo consistency."]}, {"id": "v3-light-i2", "chapter": "1 · Illumination", "kind": "v3-method-focus", "title": "I2 · Light-type effects on shadows and illumination in XR", "lead": "", "speakerNotes": "Light-type evidence: GenLit §3.2 controls a single added point light with a 5D signal; §10 explicitly bounds scope to one point light and leaves HDRI changes for future work. This is an explicit scope/parameterization choice, not proof that diffusion fundamentally supports only point lights. Its slow inference is an additional XR barrier. LightLab §3.1 and Appendix A.1 vary area size, spot cone angle and color temperature during synthetic rendering, with separate HDRI maps; §3.4 exposes intensity/color and ambient edits. Dataset coverage is not the same as independent area-size/cone-angle control at inference. Interactive Near-Field Illumination (ISMAR 2014) extracts area-light approximations from multiple HDR cameras and transmits compact lighting to mobile renderers; glossy/general BRDF and light-update limitations remain. HandLight (IEEE VR/TVCG 2026) estimates SH illumination and accumulates spatial probes, not an explicit editable catalog of point, spot and area emitters. Distinguish source type, spatial locality, color temperature and shadow softness. The proposed comparison must retain real-time/stereo measurements and matched scene/material conditions. Primary URLs: https://arxiv.org/html/2412.11224v2 (§§3.2,10); https://arxiv.org/html/2505.09608v1 (§§3.1,3.4,A.1); https://imld.de/cnt/uploads/ISMAR2014_IPAR.pdf; https://schmalstieg.github.io/pdf/Schmalstieg_452.pdf.", "transition": "Next, estimate light where the virtual subject actually stands.", "paperIds": ["genlit", "lightlab", "review-ref-65", "handlight"], "topicId": "illumination", "question": "Which light types and shadow effects can we control reliably in live XR?", "existing": "Papers cover point-light insertion, near-field area lights, and source color/intensity edits.", "gap": "Training on varied lights does not establish direct control of source size, cone angle or shadow softness in XR.", "firstTest": "Compare point, area and spot lights at matched intensity; measure shadow shape, color and update cost.", "image": "", "paperExamples": [{"id": "genlit", "name": "GenLit", "venue": "SIGGRAPH Asia", "contribution": "One added point light; control signal and training target this source."}, {"id": "lightlab", "name": "LightLab", "venue": "SIGGRAPH", "contribution": "Area/spot variation in training; controls intensity, color and ambient light."}, {"id": "review-ref-65", "name": "Interactive Near-Field Illumination", "venue": "ISMAR", "contribution": "Virtual area lights; glossy materials and light-update rate remain limited."}, {"id": "handlight", "name": "HandLight", "venue": "IEEE VR / TVCG", "contribution": "SH lighting from hands; not explicit point/spot/area source controls."}], "gaps": ["Point-light control does not cover area size or spot cone angle.", "Varied training lights do not imply editable light-type parameters.", "Joint light-type and shadow control needs validation in live stereo XR."]}, {"id": "v3-light-i3", "chapter": "1 · Illumination", "kind": "v3-method-focus", "title": "I3 · Local real lighting and shadows on virtual content", "lead": "", "speakerNotes": "HandLight is the primary reference and baseline, as explicitly requested. Environment maps represent distant light well but do not by themselves resolve strong local spatial variation. HandLight and LiMo already investigate local light; novelty must concern a remaining limitation established by their actual evaluation. Compare a global estimate, one hand probe and accumulated probes at held-out nearby virtual-object positions. Measure rendering/light error, coverage, temporal stability and update delay while the physical light or hand moves. A hand estimate is not automatically correct elsewhere; interpolation needs geometric and visibility assumptions. Separate capture, estimation/preparation, lighting updates and display budgets. The desired outcome includes both incident local illumination and visibility of real occluders from each light. Probe estimation is a candidate component, not the whole solution. The shadow experiment needs tracked or reconstructed occluder geometry, light-position estimates and a physically matched reference. Compare probe-only shading against geometry-aware shadowing; measure shadow direction/boundary error, light/color error and temporal/stereo stability. Do not imply that HandLight alone supplies scene geometry or correct real-to-virtual shadow casting.", "transition": "The next direction changes how virtual actors respond.", "paperIds": ["handlight", "limo", "review-ref-75", "review-ref-65"], "topicId": "illumination", "question": "Can nearby real lights illuminate virtual content correctly—and real objects cast shadows onto it?", "existing": "HandLight estimates light from hands; LiMo estimates spatially varying illumination.", "gap": "A local light estimate alone does not establish correct shadows from real objects onto virtual content.", "firstTest": "Move a real lamp and occluder beside a virtual prop; compare illumination and shadow placement with a matched physical prop.", "image": "assets/papers/handlight.jpg", "paperExamples": [{"id": "handlight", "name": "HandLight", "venue": "IEEE VR / TVCG", "contribution": "Hand observations → local light probes"}, {"id": "limo", "name": "LiMo", "venue": "CVPR", "contribution": "Spatially varying HDR illumination"}, {"id": "review-ref-75", "name": "Lighthouse", "venue": "CVPR", "contribution": "Stereo images → queryable lighting volume"}, {"id": "review-ref-65", "name": "Interactive Near-Field Illumination", "venue": "ISMAR", "contribution": "Near-field area lights for mobile AR"}], "gaps": ["Light estimates at a probe may differ at the virtual subject.", "Correct real-object shadows also require occluder geometry and visibility.", "Moving lights and occluders need temporally stable updates."]}, {"id": "v3-agents-goal", "chapter": "2 · Directable agents", "kind": "v3-motivation", "title": "Directable Virtual Agents", "lead": "", "speakerNotes": "SharedVP currently supports selecting/placing an animation and choosing its pose. The research goal is director-addressable behavior: hit a mark, look at a partner, act with a prop, change timing/style and retain approved parts of the take. Existing online motion control, physics controllers and text editing are positive foundations. ARDY is not simply physics-free as a complete project: its generator is kinematic and a downstream SONIC/Unitree G1 demonstration exists. Separate generator timing from full directing response. Begin with humanoids; the cute robot dinosaur represents a later embodiment question, not free retargeting. Latest proposal: core techniques, not an end-to-end production platform. Speech/text and pointing specify targets, relative speed, step extent, hold duration and event cues; outputs are editable motion references and physically executed behavior. Begin with humanoid locomotion and stable holds. Creature/robot characters, object interactions and full style are broader tracks, not all promised in the first project. Prior ISMAR 2024 dyadic gaze/head/body work and submitted SharedVP motivate data capture; neither proves this proposed technique.", "transition": "Separate what work controls, when it changes and what executes.", "paperIds": ["ardy", "closd", "motionfix"], "topicId": "agents", "bullets": ["Online motion control and physical interaction already work.", "A new note can still disturb an approved performance."], "goal": "Revise a performance live while preserving selected scene intentions.", "image": "assets/directions/agents-illustration-v4.png", "directionSummary": [{"label": "Virtual production", "text": "Rehearse before performers arrive; revise an action without rebuilding the take."}, {"label": "Current capability", "text": "Streaming motion, physical controllers and style editing provide strong foundations."}], "sharedGap": "Gap: changing movement or timing must preserve approved marks, look-at targets, contacts and cues."}, {"id": "v3-agents-coverage", "chapter": "2 · Directable agents", "kind": "v3-topic-chart", "title": "Character direction research at a glance", "lead": "", "speakerNotes": "The main pie preserves full reviewed context and highlights the current primary emphasis. Source tags are multi-valued; each presentation bucket uses an explicit first-match rule. Motion output, physical execution and full input-to-visible latency differ. ARDY has a downstream physical tracker demo; a kinematic output bucket does not mean the project has no physical demonstration. Surveys/datasets/planning remain in the fourth context group. STyMo and Walk Like This are proposal-directed primary-source additions.", "transition": "Continue from the task to evidence, gaps and a bounded first test.", "paperIds": [], "topicId": "agents", "reviewBranch": "A1"}, {"id": "v3-agents-literature-a2", "chapter": "2 · Directable agents", "kind": "v3-topic-chart", "title": "Directing prop and partner interaction", "lead": "", "speakerNotes": "The main pie preserves full reviewed context and highlights the current primary emphasis. Source tags are multi-valued; each presentation bucket uses an explicit first-match rule. Motion output, physical execution and full input-to-visible latency differ. ARDY has a downstream physical tracker demo; a kinematic output bucket does not mean the project has no physical demonstration. Surveys/datasets/planning remain in the fourth context group. STyMo and Walk Like This are proposal-directed primary-source additions.", "transition": "Continue from the task to evidence, gaps and a bounded first test.", "paperIds": [], "topicId": "agents", "reviewBranch": "A2"}, {"id": "v3-agents-literature-a3", "chapter": "2 · Directable agents", "kind": "v3-topic-chart", "title": "Changing style and revising takes", "lead": "", "speakerNotes": "The main pie preserves full reviewed context and highlights the current primary emphasis. Source tags are multi-valued; each presentation bucket uses an explicit first-match rule. Motion output, physical execution and full input-to-visible latency differ. ARDY has a downstream physical tracker demo; a kinematic output bucket does not mean the project has no physical demonstration. Surveys/datasets/planning remain in the fourth context group. STyMo and Walk Like This are proposal-directed primary-source additions.", "transition": "Continue from the task to evidence, gaps and a bounded first test.", "paperIds": [], "topicId": "agents", "reviewBranch": "A3"}, {"id": "v3-agents-subtopics", "chapter": "2 · Directable agents", "kind": "v3-subtopics", "title": "Three actor-direction subtopics", "lead": "", "speakerNotes": "Three bounded candidate tracks preserve the original directing agenda. The latest proposal focuses first on A1; A2 and A3 are follow-on research options, not simultaneous internship deliverables.", "transition": "A first test should reveal whether composition adds value.", "paperIds": ["ardy", "closd", "motionfix", "gaits"], "topicId": "agents", "items": [{"title": "A1 · Spatial and temporal direction under physics", "question": "Ground relative speed, pose, look-at and timing notes while preserving chosen marks and cues.", "paperIds": ["ardy", "closd", "body-part-phase", "scheduled-inpainting"]}, {"title": "A2 · Directable interaction with props and partners", "question": "Revise object and partner interactions while retaining the contacts and spatial relationships that matter.", "paperIds": ["lyric", "interagent", "ready-to-react", "closd"]}, {"title": "A3 · Editable style while preserving performance intent", "question": "Change expressive style or a local motion detail while preserving approved action and timing.", "paperIds": ["stymo", "walk-like-this", "gaits", "motionfix"]}]}, {"id": "v3-agents-first-test", "chapter": "2 · Directable agents", "kind": "v3-method-focus", "title": "A1 · Spatial and temporal direction under physics", "lead": "", "speakerNotes": "Latest proposal internship focus: structured inputs first, then speech/pointing. Encode root targets, head targets, relative speed/step extent, hold duration and event windows separately. ARDY provides reference generation, CLoSD/MaskedMimic provide candidate tracker foundations; composition already exists in these sources, so novelty must concern retained intent through revision and execution, not merely combining text and paths. Compare fixed retiming/tracking versus condition-aware revision/adapted tracking; log parsing, generation, buffering, control and display. Measure mark/cue/head error, requested speed/hold adherence, falls and response. Head orientation is not precise eye gaze. Contradictory conditions should be reported. Training data: licensed motion, calibrated scene-linked direction logs and demonstrations; simulation/Isaac Lab for tracker adaptation. Source-specific evidence remains in each paper panel.", "transition": "Continue from the task to evidence, gaps and a bounded first test.", "paperIds": ["ardy", "closd", "smartbody-gaze2009", "scheduled-inpainting"], "topicId": "agents", "question": "Can “slower, look here, then hold” preserve the chosen mark and cue?", "existing": "ARDY streams constrained motion; MaskedMimic and CLoSD provide physical control foundations.", "gap": "Relative notes need a current-motion and scene reference. Head/look-at targets and event cues must survive retiming. A fast generator alone does not establish input-to-motion latency.", "gaps": ["Relative notes need a current-motion and scene reference.", "Head/look-at targets and event cues must survive retiming.", "A fast generator alone does not establish input-to-motion latency."], "firstTest": "Revise one walk-and-hold take; compare simple retiming with condition-aware revision under the same targets.", "paperExamples": [{"id": "ardy", "name": "ARDY", "venue": "SIGGRAPH / TOG", "contribution": "Streaming text, paths and sparse joint goals."}, {"id": "closd", "name": "CLoSD", "venue": "ICLR", "contribution": "Diffusion planning and RL tracking in a closed loop."}, {"id": "smartbody-gaze2009", "name": "Expressive gaze control", "venue": "AAMAS", "contribution": "Coordinated eyes, head and torso; a gaze baseline."}, {"id": "scheduled-inpainting", "name": "Scheduled Inpainting", "venue": "arXiv preprint", "contribution": "Interactive clip edits with protected regions."}], "resourceLinks": [{"label": "Simulation / adaptation: NVIDIA Isaac Lab", "url": "https://isaac-sim.github.io/IsaacLab/main/"}]}, {"id": "v3-agents-interaction", "chapter": "2 · Directable agents", "kind": "v3-method-focus", "title": "A2 · Directable interaction with props and partners", "lead": "", "speakerNotes": "Retain SP3/SP4 from original slides. Treat physical contact, intention grounding and coupled response as separate pieces. Selected work already handles interaction; do not claim absence. Use one known prop and two characters before scaling. Check object mass/shape, initial states and supported action distributions. Candidate data include paired motion/object trajectories and director annotations; license and available checkpoints must be checked. Evaluate contact duration, penetration, handover timing and preserved blocking versus unchanged models; real embodiment transfer is separate.", "transition": "Continue from the task to evidence, gaps and a bounded first test.", "paperIds": ["lyric", "interagent", "ready-to-react", "closd"], "topicId": "agents", "question": "Can “pick up the cup, then hand it to her” retain contact when the note changes?", "existing": "Contact-rich controllers and online two-character reaction models already support important parts of the task.", "gap": "Prop, hand and partner targets must be grounded in one scene. A local revision can disrupt contacts and the partner’s response. Two-character or trained-action results do not establish arbitrary ensembles.", "gaps": ["Prop, hand and partner targets must be grounded in one scene.", "A local revision can disrupt contacts and the partner’s response.", "Two-character or trained-action results do not establish arbitrary ensembles."], "firstTest": "Begin with one pickup or handover; revise its target or timing and measure contact and partner-response errors.", "paperExamples": [{"id": "lyric", "name": "LYRIC", "venue": "arXiv preprint", "contribution": "Language-driven whole-body object interaction."}, {"id": "interagent", "name": "InterAgent", "venue": "arXiv preprint", "contribution": "Physics-based multi-agent command execution."}, {"id": "ready-to-react", "name": "Ready-to-React", "venue": "ICLR", "contribution": "Online two-character reactions."}, {"id": "closd", "name": "CLoSD", "venue": "ICLR", "contribution": "Text/target-driven scene interaction in simulation."}], "resourceLinks": []}, {"id": "v3-agents-style", "chapter": "2 · Directable agents", "kind": "v3-method-focus", "title": "A3 · Editable style while preserving performance intent", "lead": "", "speakerNotes": "Disney gait authoring supplements, rather than replaces, the directing objective. STyMo §§3,5 supports controllable decomposition but offline contact optimization; Walk Like This §§4,6 uses diffusion and RL, and reports style/velocity conflicts and direction-dependent styles. These are concrete starting limits, not blanket absence of real-time style control. Keep gaze, marks and cues as approved constraints; compare with simple post-stylization projection/retiming before inventing a new model. Non-humanoid transfer is an extension, not automatic retargeting. Candidate data: short paired neutral/stylized clips, motion exemplars and director preference annotations.", "transition": "Continue from the task to evidence, gaps and a bounded first test.", "paperIds": ["stymo", "walk-like-this", "gaits", "motionfix"], "topicId": "agents", "question": "Can “more hesitant” change the performance without losing the action, mark or cue?", "existing": "Example-driven stylization, text motion edits and artist-authored robotic gaits offer complementary control.", "gap": "Style and speed can compete for the same root motion. Fast style inference can still require offline contact cleanup. Preserving approved targets through style changes needs an explicit test.", "gaps": ["Style and speed can compete for the same root motion.", "Fast style inference can still require offline contact cleanup.", "Preserving approved targets through style changes needs an explicit test."], "firstTest": "Stylize one approved walk at several intensities; compare timing, mark error, contacts and unintended changes.", "paperExamples": [{"id": "stymo", "name": "STyMo", "venue": "ACM TOG", "contribution": "Posture/rhythm controls; contact cleanup is offline."}, {"id": "walk-like-this", "name": "Walk Like This", "venue": "arXiv preprint", "contribution": "Live physical locomotion; style/velocity conflicts remain."}, {"id": "gaits", "name": "Disney gait authoring", "venue": "SIGGRAPH", "contribution": "Artist-designed gait cycles under robotic constraints."}, {"id": "motionfix", "name": "MotionFix", "venue": "SIGGRAPH Asia", "contribution": "Text edits to an existing motion clip."}], "resourceLinks": []}, {"id": "v3-robotics-goal", "chapter": "3 · XR robotics", "kind": "v3-motivation", "title": "Human Robot Interaction and Visualization in XR", "lead": "", "speakerNotes": "Return to the virtual-only digital twins in SharedVP. Equipment includes cameras, sliders, arms, gimbals, light rigs and potentially drones, but the first study needs one bounded setup. Existing proxies, robot interfaces and cinematography planners are established work. The research is how users express creative/technical intent and understand the resulting constraints and states. A visual proxy does not certify a collision-free or safe physical action; control enforcement and real-device acknowledgement remain external responsibilities. Simulate first because physical robot access is unconfirmed. Latest proposal treats equipment as a broader extension. Develop core proxy/control/feedback techniques, not a complete orchestration platform. Simulated camera arm/slider and light rigs permit controlled first tests; the proposal names VPI/SISU infrastructure as a potential later validation setting, not evidence that every device is integrated. Fixed shot decisions, proposed plans and observed physical states must remain distinct.", "transition": "Compare the control, feedback and validation already demonstrated.", "paperIds": ["reality-proxy", "cinempc", "praveena"], "topicId": "robotics", "bullets": ["XR proxies and camera planning already enable control.", "Physical equipment adds limits and coupled consequences."], "goal": "Revise equipment motion, framing and lighting while preserving approved shot intent.", "image": "assets/directions/robotics-illustration-v4.png", "directionSummary": [{"label": "Virtual production", "text": "A shot links framing, movement and lighting; one device change can invalidate another plan."}, {"label": "Current capability", "text": "XR proxies, camera planners and robot-team interfaces already support authoring and supervision."}], "sharedGap": "Gap: a feasible revision must explain equipment constraints and preserve approved shot decisions."}, {"id": "v3-robotics-coverage", "chapter": "3 · XR robotics", "kind": "v3-topic-chart", "title": "Equipment interaction research at a glance", "lead": "", "speakerNotes": "Retain all 17 reviewed records, including surveys and workflow studies. Primary emphasis is an exclusive presentation grouping, not an exclusive capability claim. Physical demonstration takes precedence over simulation for a record that includes both, but does not imply every scenario was physically tested. Interface feedback is not physical constraint enforcement. Unknowns and source reading depth remain inspectable.", "transition": "Continue from the task to evidence, gaps and a bounded first test.", "paperIds": [], "topicId": "robotics", "reviewBranch": "R1"}, {"id": "v3-robotics-literature-r2", "chapter": "3 · XR robotics", "kind": "v3-topic-chart", "title": "Shaping fluid camera and equipment motion", "lead": "", "speakerNotes": "Retain all 17 reviewed records, including surveys and workflow studies. Primary emphasis is an exclusive presentation grouping, not an exclusive capability claim. Physical demonstration takes precedence over simulation for a record that includes both, but does not imply every scenario was physically tested. Interface feedback is not physical constraint enforcement. Unknowns and source reading depth remain inspectable.", "transition": "Continue from the task to evidence, gaps and a bounded first test.", "paperIds": [], "topicId": "robotics", "reviewBranch": "R2"}, {"id": "v3-robotics-literature-r3", "chapter": "3 · XR robotics", "kind": "v3-topic-chart", "title": "Supervising coordinated equipment changes", "lead": "", "speakerNotes": "Retain all 17 reviewed records, including surveys and workflow studies. Primary emphasis is an exclusive presentation grouping, not an exclusive capability claim. Physical demonstration takes precedence over simulation for a record that includes both, but does not imply every scenario was physically tested. Interface feedback is not physical constraint enforcement. Unknowns and source reading depth remain inspectable.", "transition": "Continue from the task to evidence, gaps and a bounded first test.", "paperIds": [], "topicId": "robotics", "reviewBranch": "R3"}, {"id": "v3-robotics-subtopics", "chapter": "3 · XR robotics", "kind": "v3-subtopics", "title": "Three XR–robotics subtopics", "lead": "", "speakerNotes": "These preserve the existing proxy, pseudo-haptic and coordination tracks. Equipment is a broader extension in the latest proposal. Start with one simulated plant and an established controller so an interface contribution can be isolated.", "transition": "Start with one camera move that needs repair.", "paperIds": ["reality-proxy", "xavier", "mrpilot"], "topicId": "robotics", "items": [{"title": "R1 · Intent-preserving equipment proxies", "question": "Translate spatial shot goals into feasible camera or light motion while preserving selected creative constraints.", "paperIds": ["reality-proxy", "cinempc", "mr-3d-teaming", "heterogeneous-mr"]}, {"title": "R2 · Perceptual affordances for physics-informed motion", "question": "Use perceptual feedback and physical motion models without hiding the true equipment state.", "paperIds": ["hosl", "praveena", "xavier", "reality-proxy"]}, {"title": "R3 · Human-in-the-loop camera and light coordination", "question": "Preview and revise camera–light dependencies while keeping human decisions and observed execution explicit.", "paperIds": ["mrpilot", "spot-on", "vrgit", "cinempc"]}]}, {"id": "v3-robotics-first-test", "chapter": "3 · XR robotics", "kind": "v3-method-focus", "title": "R1 · Intent-preserving equipment proxies", "lead": "", "speakerNotes": "Motivation: SharedVP controls equipment twins virtually. The research concerns the mapping from spatial creative/technical intent to feasible control, with preservation of selected framing, not a claim that proxy selection itself is new. Reality Proxy is not a motion planner. CineMPC already solves artistic/technical camera constraints; use it or a comparable fixed planner as a baseline. Simulation first: known geometry, identical controller and plant, calibrated lens and framing target. Measure framing deviation, task time, corrections and constraint understanding; physical deployment later requires calibration and observed-state confirmation.", "transition": "Continue from the task to evidence, gaps and a bounded first test.", "paperIds": ["reality-proxy", "cinempc", "mr-3d-teaming", "heterogeneous-mr"], "topicId": "robotics", "question": "Can a spatial proxy repair an infeasible camera move without changing the intended framing?", "existing": "Reality Proxy supports abstract selection; CineMPC turns cinematic goals into constrained camera behavior.", "gap": "Selecting a proxy does not establish feasible robot motion. The user needs to understand which constraint forces a shot change. A repaired path must preserve selected framing and lens intentions.", "gaps": ["Selecting a proxy does not establish feasible robot motion.", "The user needs to understand which constraint forces a shot change.", "A repaired path must preserve selected framing and lens intentions."], "firstTest": "Use one simulated arm or slider; compare ordinary preview with an explanatory proxy using the same planner.", "paperExamples": [{"id": "reality-proxy", "name": "Reality Proxy", "venue": "UIST", "contribution": "Nearby abstract controls for real-world objects."}, {"id": "cinempc", "name": "CineMPC", "venue": "IEEE T-RO", "contribution": "Joint camera pose, lens and composition control."}, {"id": "mr-3d-teaming", "name": "3D MR robot teaming", "venue": "arXiv preprint", "contribution": "Miniature robot dragging with viable-goal correction."}, {"id": "heterogeneous-mr", "name": "Heterogeneous MR", "venue": "arXiv preprint", "contribution": "Extractable controls tailored to different robot types."}], "resourceLinks": []}, {"id": "v3-robotics-fluid-motion", "chapter": "3 · XR robotics", "kind": "v3-method-focus", "title": "R2 · Perceptual affordances for physics-informed motion", "lead": "", "speakerNotes": "Preserve the original pseudo-haptic/physical-affordance topic. Visual gain, lag and trajectory smoothing can suggest inertia or constraints; they are not actuator forces. Isolate feedback by holding the controller and simulated plant fixed. Compare motion smoothness, framing error, correction time, agency and understanding of actual equipment lag/position. Hoesl et al. identify limited treatment of expressive exploration; Praveena et al. is an expert probe, not a large controlled trial. Do not treat surveys as implementation evidence. Candidate setup: tracked XR controller, simulated rail/arm dynamics and reproducible framing task.", "transition": "Continue from the task to evidence, gaps and a bounded first test.", "paperIds": ["hosl", "praveena", "xavier", "reality-proxy"], "topicId": "robotics", "question": "Can an XR proxy make camera motion feel fluid while revealing the real equipment response?", "existing": "Camera-motion studies and pseudo-haptics describe useful input mappings and perceptual feedback.", "gap": "A smooth virtual proxy can hide lag or physical limits. Perceived resistance does not guarantee feasible equipment motion. Cinematic expressiveness needs task evidence beyond general interaction preference.", "gaps": ["A smooth virtual proxy can hide lag or physical limits.", "Perceived resistance does not guarantee feasible equipment motion.", "Cinematic expressiveness needs task evidence beyond general interaction preference."], "firstTest": "Compare direct mapping and motion-gain feedback on one camera move, with identical dynamics and framing targets.", "paperExamples": [{"id": "hosl", "name": "Cinematographic motion control", "venue": "INTERACT", "contribution": "Compares ways to author and review camera motion."}, {"id": "praveena", "name": "Collaborative cinematography", "venue": "CHI EA", "contribution": "Practitioner exploration of camera-robot collaboration."}, {"id": "xavier", "name": "Pseudo-haptics survey", "venue": "IEEE Access", "contribution": "Perceptual feedback vocabulary, not a camera-rig validation."}, {"id": "reality-proxy", "name": "Reality Proxy", "venue": "UIST", "contribution": "Abstract interaction target; no physical force feedback."}], "resourceLinks": []}, {"id": "v3-robotics-coordination", "chapter": "3 · XR robotics", "kind": "v3-method-focus", "title": "R3 · Human-in-the-loop camera and light coordination", "lead": "", "speakerNotes": "Link directly to shared virtual production: a camera revision changes screen-space composition, key-light direction and equipment placement. The proposal describes orchestration as a longer-term use of core techniques. Begin with one camera and one light, not arbitrary multi-equipment autonomy. Make a shot dependency explicit (e.g., maintain camera-relative key-light direction and frame an actor). Baseline independent control with the same planners. Measure retained shot constraints, repair actions and state understanding. Lighting feasibility and real-actuator acknowledgement are separate from MR illumination rendering in Direction 1. VRGit supports virtual versioning, not rollback of physical state. MRPilot is VR-only in the inspected version; Spot-On tasks do not measure cinematic quality.", "transition": "Continue from the task to evidence, gaps and a bounded first test.", "paperIds": ["mrpilot", "spot-on", "vrgit", "cinempc"], "topicId": "robotics", "question": "When a shot changes, can operators see and revise the linked camera and lighting consequences?", "existing": "MR robot-team supervision and spatial version histories already make plans and alternatives inspectable.", "gap": "Robot-team interfaces do not establish preservation of cinematic camera–light intent. A saved virtual state is not a physical undo operation. Proposed, executing and observed equipment states can diverge.", "gaps": ["Robot-team interfaces do not establish preservation of cinematic camera–light intent.", "A saved virtual state is not a physical undo operation.", "Proposed, executing and observed equipment states can diverge."], "firstTest": "Change one camera path in simulation; compare independent device controls with an explicit camera–light dependency preview.", "paperExamples": [{"id": "mrpilot", "name": "MRPilot", "venue": "arXiv preprint", "contribution": "Inspect and intervene in robot-team plans; VR evaluation."}, {"id": "spot-on", "name": "Spot-On", "venue": "arXiv preprint", "contribution": "Scene-graph actions for multi-robot cooperation."}, {"id": "vrgit", "name": "VRGit", "venue": "CHI", "contribution": "Collaborative spatial history and alternative states."}, {"id": "cinempc", "name": "CineMPC", "venue": "IEEE T-RO", "contribution": "Camera composition/control baseline; not lighting orchestration."}], "resourceLinks": []}, {"id": "v3-evaluation-baseline", "chapter": "Shared virtual production", "kind": "v3-evaluation", "title": "Keep the existing evaluation baseline", "lead": "16 October 2026 · six user-rated criteria", "speakerNotes": "These are the user's supplied ratings, not agent-generated scores or objective rankings. Totals are unweighted sums of six 0–100 criteria; do not normalize them into an evidence-based recommendation. Illumination:85,80,80,80,90,90=505. Agents:85,80,80,75,75,80=475. Robotics:80,70,75,70,70,80=445. The date is the existing stored version label, not a new evaluation date. Preserve the original rationales in the discussion workspace. No new ratings are made in this version.", "transition": "Any update should explain what changed and why.", "paperIds": [], "criteria": ["Interest", "Talent", "Career", "Feasibility", "Competitiveness", "Significance"], "evaluationVersion": "2026-10-16", "rows": [{"topicId": "illumination", "title": "Illumination", "scores": [85, 80, 80, 80, 90, 90], "total": 505}, {"topicId": "agents", "title": "Agents", "scores": [85, 80, 80, 75, 75, 80], "total": 475}, {"topicId": "robotics", "title": "XR robotics", "scores": [80, 70, 75, 70, 70, 80], "total": 445}], "caption": "Personal ratings support discussion; evidence still needs scrutiny."}, {"id": "v3-evaluation-discussion", "chapter": "Shared virtual production", "kind": "v3-evaluation", "title": "What evidence would change the decision?", "lead": "Update the previous version; do not restart the ratings.", "speakerNotes": "Keep a versioned ledger with date, criterion, old score, delta, new score, reason and evidence. Leave deltas/new ratings blank until the user supplies them. Examples such as +5 or −5 are update mechanics, not proposed ratings. Discuss uncertainties openly so the PI can offer useful feedback: actual baseline reproduction, whether a residual failure remains, data and hardware access, and a feasible first-paper boundary. Distinguish personal interest/career fit from evidence of novelty or method feasibility. The aim is to choose a first experiment and a useful fallback, not manufacture a final ranking.", "transition": "Choose the first experiment together.", "paperIds": [], "questions": ["Which failure can we reproduce?", "What would a stronger baseline remove?", "Which data or equipment can we access?", "What is the smallest useful first paper?"], "revisionFields": ["criterion", "previous score", "delta", "reason", "evidence"], "newScores": null}]};
